import Foundation
import Testing
@testable import OrbisCore

// SC121 / APNS-L21: exact host/turn ownership and negative-inventory safety.
@Suite("Delivered reply notification cleanup")
struct ReplyNotificationCleanupTests {
    private typealias Cleanup = ReplyNotificationCleanup
    private let checked = Date(timeIntervalSince1970: 200)
    // Fixed UTF-8 SHA-256 vectors from the released Host format, not generated by the matcher.
    private let pending = "a9729217f18c3cf534794e0d187cbcab939a114ce2997ca07952a656f3e1553f"
    private let done = "c46b7163ec8034150ddaae3e70aa837a49d27504810569d38c1d5e3a666ca193"
    private let oldTurn = Cleanup.Turn(runtime: "runtime", session: "session", id: "old", startedAt: 1000)
    private let newTurn = Cleanup.Turn(runtime: "runtime", session: "session", id: "new", startedAt: 2000)

    private func remote(_ id: String, _ event: String?, host: String = "a", thread: String = "",
                        category: String = "approval-requested", date: Date = Date(timeIntervalSince1970: 100)) -> Cleanup.Alert {
        var payload: [String: Any] = ["v": 1, "hostId": host, "category": category]
        payload["eventId"] = event
        return .init(id: id, date: date, thread: thread, remote: true, userInfo: ["orbis": payload])
    }

    private func local(_ turn: String, host: String = "a", pairing: String? = nil) -> Cleanup.Alert {
        let id = Data([host, "session", "epoch", turn].joined(separator: "\u{0}").utf8).base64EncodedString()
        let userInfo: [String: Any]
        if let pairing {
            userInfo = ["orbis": ["v": 1, "hostId": host, "category": "task-completed", "sessionId": "session", "pairingKey": pairing]]
        } else { userInfo = ["hostId": host, "sessionId": "session"] }
        return .init(id: id, date: checked, thread: "", remote: false, userInfo: userInfo)
    }

    @Test func approvalsAreHostScopedAndUnknownLegacyIdsNeedEmptyInventory() {
        var facts = Cleanup.HostFacts(generation: UUID(), approvals: ["runtime": ["pending"]], approvalsConfirmedThrough: checked)
        var state = Cleanup.State(pairings: ["a": "key-a", "b": "key-b"], pairingsConfirmed: true, retiredThrough: [:], hosts: ["a": facts])
        let alerts = [remote("pending", pending), remote("resolved", done), remote("legacy", "old-format"),
                      remote("missing-event", nil), remote("other-host", done, host: "b"),
                      remote("mismatch", done, thread: NotificationSource.threadIdentifier("b")),
                      remote("completion", done, category: "task-completed")]
        #expect(Cleanup.plan(alerts, state: state).remove == ["resolved"])
        facts.approvals = ["runtime": []]; state.hosts["a"] = facts
        #expect(Cleanup.plan(alerts, state: state).remove == ["pending", "resolved", "legacy", "missing-event"])
        facts.approvals = nil; state.hosts["a"] = facts
        #expect(Cleanup.plan(alerts, state: state).remove.isEmpty)
    }

    @Test func newApprovalCanBeatStateButKnownSettlementCanBeatDelivery() {
        var facts = Cleanup.HostFacts(generation: UUID(), approvals: ["runtime": []], approvalsConfirmedThrough: checked)
        var state = Cleanup.State(pairings: ["a": "key"], pairingsConfirmed: true, retiredThrough: [:], hosts: ["a": facts])
        let late = checked.addingTimeInterval(1)
        let alerts = [remote("potentially-pending", pending, date: late), remote("already-resolved", done, date: late)]
        let plan = Cleanup.plan(alerts, state: state)
        #expect(plan.remove.isEmpty)
        #expect(plan.recheck == ["a": late])
        facts.approvals = ["runtime": ["pending"]]
        facts.settledApprovals = ["runtime": ["done"]]; state.hosts["a"] = facts
        #expect(Cleanup.plan(alerts, state: state).remove == ["already-resolved"])
    }

    @Test func completionMatchesKnownTurnAndPreservesLatestAndOtherSessions() {
        let legacy = local("old")
        let latest = local("new", pairing: "key")
        let other = local("old", host: "b")
        let oldRemote = remote("old-remote", "536d5428f4d6c130fb8f604f8cc63663b861c70ab411f7138aacde129f96015c", category: "task-completed")
        let newRemote = remote("new-remote", "7fab6ba80b225b03c7a23adf8d2ceb1bf388ef950b5720fedafb8a56109f8b43", category: "task-completed")
        let unknown = remote("unmatched-remote", done, category: "task-completed")
        let alerts = [legacy, latest, other, oldRemote, newRemote, unknown]
        var facts = Cleanup.HostFacts(generation: UUID(), latestTurns: [newTurn], knownCompletions: [oldTurn],
            localTurnStarts: [.init(session: "session", epoch: "epoch", id: "old"): oldTurn.startedAt])
        var state = Cleanup.State(pairings: ["a": "key", "b": "key"], pairingsConfirmed: true, retiredThrough: [:], hosts: ["a": facts])
        #expect(Cleanup.plan(alerts, state: state).remove == [legacy.id, oldRemote.id])
        facts.viewedSessions = ["session"]; state.hosts["a"] = facts
        #expect(Cleanup.plan(alerts, state: state).remove == [legacy.id, latest.id, oldRemote.id, newRemote.id])
        facts.viewedSessions = ["different-session"]; state.hosts["a"] = facts
        #expect(Cleanup.plan([latest, newRemote, other, unknown], state: state).remove.isEmpty)
        state.hosts = [:]
        #expect(Cleanup.plan(alerts, state: state).remove.isEmpty)
    }

    @Test func pairingRetirementCoversGroupedAndReleasedPayloadsWithoutTouchingNewPairing() {
        let grouped = Cleanup.Alert(id: "grouped", date: checked, thread: NotificationSource.threadIdentifier("a"), remote: true, userInfo: [:])
        let flat = local("old")
        let staleLocalKey = local("older", pairing: "previous")
        let newAlert = remote("new-pairing", pending, date: checked.addingTimeInterval(1))
        let unrelated = Cleanup.Alert(id: "unrelated", date: checked, thread: "elsewhere", remote: false, userInfo: [:])
        let alerts = [grouped, flat, staleLocalKey, newAlert, unrelated, remote("peer", done, host: "b")]
        var state = Cleanup.State(pairings: ["a": "key", "b": "key-b"], pairingsConfirmed: true, retiredThrough: ["a": checked], hosts: [:])
        #expect(Cleanup.plan(alerts, state: state).remove == [grouped.id, flat.id, staleLocalKey.id])
        state.pairings["a"] = nil
        #expect(Cleanup.plan(alerts, state: state).remove == [grouped.id, flat.id, staleLocalKey.id, newAlert.id])
        state.retiredThrough = [:]
        #expect(Cleanup.plan(alerts, state: state).remove == [flat.id, staleLocalKey.id, newAlert.id])
        state.pairingsConfirmed = false
        #expect(Cleanup.plan(alerts, state: state).remove.isEmpty)
    }
}
